#include <iostream>
#include <functional>
#include <memory>
#include <vector>
#include <string>
#include <mutex>
#include <future>
#include <unordered_map>
#include <cassert>

namespace serialization {

class SerializationContext;

using CompletionHandler = std::function<void(SerializationContext&, const std::string&)>;

class ObjectRegistry {
public:
    static ObjectRegistry& instance() {
        static ObjectRegistry reg;
        return reg;
    }

    void register_handler(const std::string& type_id, CompletionHandler handler) {
        std::lock_guard<std::mutex> lock(mutex_);
        handlers_[type_id] = std::move(handler);
    }

    CompletionHandler get_handler(const std::string& type_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = handlers_.find(type_id);
        if (it != handlers_.end()) return it->second;
        return nullptr;
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, CompletionHandler> handlers_;
};

class SerializationContext {
public:
    enum class State { IDLE, SERIALIZING, FINALIZING, COMPLETE };

    SerializationContext() : state_(State::IDLE), depth_(0) {}

    void begin_serialization() {
        lock_.lock();
        state_ = State::SERIALIZING;
        depth_ = 0;
        buffer_.clear();
        lock_.unlock();
    }

    // Async serialize a nested object - may invoke callbacks
    std::future<std::string> serialize_object(const std::string& type_id, const std::string& data) {
        return std::async(std::launch::deferred, [this, type_id, data]() -> std::string {
            lock_.lock();
            depth_++;
            buffer_.push_back("[" + type_id + ":");
            lock_.unlock();

            // Process nested serialization via registered handler
            auto handler = ObjectRegistry::instance().get_handler(type_id);
            if (handler) {
                // Handler may re-enter serialize_object
                handler(*this, data);
            }

            lock_.lock();
            buffer_.push_back(data);
            buffer_.push_back("]");
            depth_--;

            // Critical section: finalize if we're back at root
            if (depth_ == 0) {
                state_ = State::FINALIZING;
                auto result = finalize_internal();
                state_ = State::COMPLETE;
                lock_.unlock();
                return result;
            }
            lock_.unlock();
            return "";
        });
    }

    // Called during async completion to append transformed data
    void append_transformed(const std::string& transformed) {
        // No lock here - assumes caller holds context lock
        // But during reentrant handler calls, lock is NOT held
        buffer_.push_back(transformed);
        if (state_ == State::FINALIZING) {
            // Race: buffer modified during finalization
            buffer_.back() = "FINALIZED:" + transformed;
        }
    }

    std::string get_result() {
        std::lock_guard<std::mutex> lock(lock_);
        std::string result;
        for (auto& s : buffer_) result += s;
        return result;
    }

private:
    std::string finalize_internal() {
        // Iterates buffer while it may be concurrently modified
        std::string result;
        for (size_t i = 0; i < buffer_.size(); i++) {
            result += buffer_[i];
        }
        return result;
    }

    std::mutex lock_;
    State state_;
    int depth_;
    std::vector<std::string> buffer_;
};

class AsyncSerializer {
public:
    AsyncSerializer() : ctx_(std::make_shared<SerializationContext>()) {}

    void setup_handlers() {
        // Register a handler that re-enters serialization
        ObjectRegistry::instance().register_handler("nested",
            [](SerializationContext& ctx, const std::string& data) {
                // This re-enters serialize_object while lock is not held
                // between the unlock() after depth_++ and the handler call
                auto inner = ctx.serialize_object("leaf", "inner_" + data);
                auto result = inner.get(); // blocks, causes reentrant lock acquisition
                ctx.append_transformed(result);
            });

        ObjectRegistry::instance().register_handler("leaf",
            [](SerializationContext& ctx, const std::string& data) {
                ctx.append_transformed("LEAF:" + data);
            });
    }

    std::string serialize(const std::string& type_id, const std::string& data) {
        ctx_->begin_serialization();
        auto future = ctx_->serialize_object(type_id, data);
        return future.get();
    }

private:
    std::shared_ptr<SerializationContext> ctx_;
};

} // namespace serialization

int main() {
    serialization::AsyncSerializer serializer;
    serializer.setup_handlers();

    // This triggers the reentrant path
    auto result = serializer.serialize("nested", "payload");
    std::cout << "Result: " << result << std::endl;

    return 0;
}
